import { NextRequest } from 'next/server';
import { get } from '@/lib/db';
import { absoluteMediaPath, readDerivative, verifyMediaSignature } from '@/lib/media/storage';
import fs from 'node:fs';

export const dynamic = 'force-dynamic';

/**
 * Public media endpoint used only by platforms that require an image URL.
 * Every request must carry a valid HMAC signature generated by the server,
 * so the media library is not publicly enumerable.
 */
export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  const { id } = await ctx.params;
  const url = new URL(req.url);
  const preset = url.searchParams.get('preset') || 'original';
  const sig = url.searchParams.get('sig') || '';
  if (!sig || !verifyMediaSignature(id, sig, preset)) {
    return new Response('Invalid or missing signature', { status: 403 });
  }
  const row = get<{ filename: string; mime: string; kind: string }>(
    'SELECT filename, mime, kind FROM media_assets WHERE id = ? AND deleted_at IS NULL',
    id
  );
  if (!row) return new Response('Not found', { status: 404 });
  try {
    if (preset !== 'original' && row.kind === 'image') {
      const derivative = readDerivative(id, preset);
      if (derivative) {
        return new Response(new Uint8Array(derivative), {
          headers: { 'content-type': 'image/jpeg', 'cache-control': 'public, max-age=3600' },
        });
      }
    }
    const buffer = fs.readFileSync(absoluteMediaPath(row.filename));
    return new Response(new Uint8Array(buffer), {
      headers: { 'content-type': row.mime || 'application/octet-stream', 'cache-control': 'public, max-age=3600' },
    });
  } catch {
    return new Response('File unavailable', { status: 410 });
  }
}
